O = {
"c384:xo53_1_67": ("**위팔두갈래근 반사** 수준", "위팔두갈래근 반사는 **C5(C6)** 이에요. C7은 위팔세갈래근 반사예요.", "위팔두갈래근 반사는 **C5(C6)** 수준이다.", "두갈래 5·6, 위팔노 6, 세갈래 7", 5),
"c384:xt53_1_67": ("위팔두갈래근 반사 **신경 수준**", "위팔두갈래근 반사는 **C5(C6)** 수준이에요.", "'C7'로 바꾸면 틀려요. C7은 위팔세갈래근이에요.", "두갈래 5·6, 세갈래 7", 5),
"c384:xo50_1_67": ("반사의 **경로**", "반사는 들신경 → 중추 → 날신경이 모두 있어야 일어나요. 감각과 운동 경로의 상호작용을 보는 검사가 맞아요.", "'운동 경로만 본다'고 하면 틀려요.", "반사 = 들어가고 나오는 길 모두", 2),
"c384:xo50_1_82": ("**호프만**과 **바빈스키**", "발바닥을 긁는 것은 **바빈스키**, 가운데손가락 끝을 튕기는 것은 **호프만** 반사예요.", "호프만 반사는 **가운데손가락 끝을 튕겨** 확인한다.", "손 호프만, 발 바빈스키", 4),
"c384:xt50_1_82": ("손가락 튕길 때 **엄지·검지 굽힘**", "가운데손가락 끝을 튕길 때 엄지·검지가 굽으면 **호프만 반사** 양성(위운동신경세포 징후)이에요.", "'바빈스키 반사'로 바꾸면 틀려요.", "손 호프만, 발 바빈스키", 4),
"c385:xo53_1_92": ("엎드려 들 때 **몸 전체 폄**", "엎드린 채 들어 올리면 머리를 들며 척추·팔다리가 펴지는 것은 **란다우 반응**이에요. 양서류 반응은 골반을 들면 같은 쪽 엉덩·무릎이 굽는 반응이에요.", "엎드려 머리를 들 때 몸 전체가 펴지는 반응은 **란다우 반응**이다.", "몸 펴기 = 란다우, 다리 굽힘 = 양서류", 3),
"c385:xo52_1_89": ("**낙하산 반응** 시기", "낙하산 반응은 생후 **6~9개월에 나타나 평생** 유지돼요.", "낙하산 반응은 생후 6~9개월에 나타나 **평생 지속**된다.", "보호반응은 사라지지 않는다", 4),
"c385:xo51_1_89": ("**평형반응** 수준", "평형반응은 **대뇌겉질** 수준이에요. 중간뇌 수준은 바로잡기 반응이에요.", "평형반응은 **대뇌겉질** 수준 반응이다.", "척수 → 뇌줄기 → 중간뇌(바로잡기) → 겉질(평형)", 4),
"c385:xo50_1_89": ("**비대칭 긴장목반사**", "비대칭 긴장목반사는 뇌줄기 수준 원시반사로 생후 4~6개월쯤 **통합(소실)** 돼요. 남아 있으면 비정상이에요.", "비대칭 긴장목반사는 영아기에 **통합되어 사라진다**.", "원시반사는 사라져야 정상", 4),
"c386:xo53_1_68": ("손에 쥔 **물체 알아맞히기**", "눈을 감고 손에 쥔 물체를 알아맞히는 것은 **입체감각인식**이에요. 두점식별은 두 점을 구분하는 최소 거리예요.", "손에 쥔 물체를 알아맞히는 검사는 **입체감각인식** 검사다.", "쥐고 맞히기 = 입체감각, 두 점 = 거리", 4),
"c386:xo52_1_67": ("**입체감각**의 정의", "입체감각은 **손에 쥔 물체**를 알아보는 감각이에요. 피부에 쓴 숫자를 맞히는 것은 피부그림감각(書字覺)이에요.", "입체감각은 **손에 쥔 물체**를 알아보는 감각이다.", "쥐면 입체, 쓰면 피부그림", 4),
"c386:xo52_1_87": ("**발한 검사**", "땀이 나는 곳이 보라색으로 변하는 **요오드-녹말 검사**로 땀(자율신경) 손상을 확인해요.", "발한 검사는 **요오드-녹말 검사**다.", "보라색 = 땀 나는 곳", 2, "얼음물 담그기 검사가 어떤 검사로 출제되었는지는 보기 문맥을 확인하세요."),
"c386:xo51_1_68": ("**핀** 검사와 감각 종류", "핀으로 찌르는 통증 검사는 **얕은감각** 검사예요. 진동·위치감각이 깊은감각이에요.", "핀으로 찌르는 검사는 **얕은감각(통증)** 검사다.", "피부 = 얕은, 관절·진동 = 깊은", 4),
"c386:xo50_1_88": ("**두점식별감각**의 정의", "두점식별은 피부에 닿은 두 점을 구분하는 최소 거리예요. 만져서 물건 이름을 맞히는 것은 **입체감각인식**이에요.", "만져서 물건 이름을 맞히는 능력은 **입체감각인식**이다.", "두 점 = 거리, 물건 = 입체", 4),
"c387:xo53_1_91": ("**구역반사**의 신경", "구역·삼킴 반사는 **혀인두신경(IX)과 미주신경(X)** 을 봐요. 얼굴신경은 표정근을 맡아요.", "구역반사는 **혀인두신경·미주신경** 검사다.", "구역 = IX·X", 4),
"c387:xt53_1_91": ("구역·삼킴 반사 **신경**", "구역·삼킴 반사는 혀인두신경(IX)이 들어가고 **미주신경(X)** 이 나가요.", "'얼굴신경'으로 바꾸면 틀려요.", "구역 = IX·X", 4),
"c387:xo50_1_87": ("**삼차신경** 검사", "삼차신경 손상은 **각막반사**(들신경)로 확인해요. 구역반사는 IX·X예요.", "삼차신경 손상은 **각막반사**로 확인한다.", "각막 = 삼차(들) + 얼굴(날)", 4),
"c387:xt50_1_87": ("가장 큰 뇌신경 **(3가지)** 검사", "가지가 3개인 가장 큰 뇌신경은 삼차신경이고, **각막반사**로 손상을 확인해요.", "'구역반사'로 바꾸면 틀려요.", "삼차 = 각막반사", 4),
"c388:xo52_1_66": ("**S1** 손상 약화 움직임", "발등굽힘은 **L4**, S1은 **가쪽번짐·발바닥굽힘**을 맡아요.", "S1 손상은 발목 **가쪽번짐·발바닥굽힘**을 약하게 만든다.", "L4 발등굽힘, L5 엄지 폄, S1 가쪽번짐", 5),
"c388:xt52_1_66": ("아킬레스 반사↓ + **발 가쪽** 감각↓", "아킬레스 반사와 발 가쪽 감각은 S1이라, 약해지는 움직임은 **발목 가쪽번짐**이에요.", "'발등굽힘(L4)'으로 바꾸면 틀려요.", "S1 = 아킬레스 + 가쪽", 5),
"c388:xo51_1_66": ("**C5** 감각 영역", "C5는 어깨세모근 위 **위팔 가쪽**이에요. 아래팔 가쪽과 엄지는 C6이에요.", "C5 신경뿌리는 **위팔 가쪽** 감각을 담당한다.", "C5 위팔, C6 엄지, C7 가운데, C8 새끼", 5),
"c388:xt51_1_66": ("두갈래 반사↓ + **어깨 벌림** 약화", "두갈래 반사와 어깨 벌림은 C5이므로 감각 저하 부위는 **위팔 가쪽(C5)** 이에요.", "'엄지(C6)'로 바꾸면 틀려요.", "C5 = 어깨세모근 위", 5),
"c389:xo51_2_30": ("**경직**과 깊은힘줄반사", "경직은 위운동신경세포 손상으로 깊은힘줄반사가 **항진**되고 클로누스가 나타나요. 반사 소실은 아래운동신경세포 손상이에요.", "경직이 있으면 깊은힘줄반사가 **항진**된다.", "위 손상 = 항진, 아래 손상 = 소실", 5),
"c389:xt51_2_30": ("**경직**의 특징", "경직(위운동신경세포 손상)은 반사 항진과 **간대성경련(클로누스)** 이 특징이에요.", "'반사 소실'로 바꾸면 틀려요.", "경직 = 클로누스", 5),
"c390:xo52_1_85": ("**린네 검사**", "린네 검사는 소리굽쇠로 하는 **청력** 검사예요. 협응(겨냥이상)은 손가락 맞대기·손가락-코 검사로 봐요.", "린네 검사는 **청력** 검사다.", "소리굽쇠 = 린네·웨버", 3),
"c390:xt52_1_85": ("**겨냥이상** 검사", "운동의 거리·범위 조절 장애(겨냥이상)는 **손가락 맞대기**·손가락-코 검사로 봐요.", "'린네 검사'로 바꾸면 틀려요.", "거리 조절 = 손가락 맞대기", 3),
"c391:xo50_1_80": ("**AIS C**와 **D**", "핵심근 절반 이상이 근력 3 **미만**이면 **C**, 3 **이상**이면 D예요.", "핵심근 절반 이상이 근력 3 미만이면 **AIS C**다.", "3 미만 C, 3 이상 D", 5),
"c391:xt50_1_80": ("핵심근 절반 이상 **3 이상**", "불완전손상이면서 손상 아래 핵심근 절반 이상이 3 이상이면 **AIS D**예요.", "'AIS C'로 바꾸면 틀려요.", "3 이상 = D", 5),
"c392:xo52_1_80": ("**셋째 손가락** 감각", "셋째(가운데) 손가락 감각은 **C7**이에요. C6 완전손상이면 엄지까지만 감각이 있어요.", "셋째 손가락 감각은 **C7** 손상 환자부터 있다.", "C6 엄지, C7 가운데", 4),
"c392:xt52_1_80": ("엉덩이 들기 + **셋째 손가락**", "C7은 위팔세갈래근으로 팔꿉을 펴 엉덩이를 들 수 있고, 셋째 손가락 감각을 담당해요. **C7**이에요.", "'C6'으로 바꾸면 틀려요.", "팔꿉 펴기 = C7", 4),
"c392:xo51_1_80": ("**C4** 완전 손상", "C4 완전 손상은 어깨올림과 가로막 일부만 남고 팔 기능은 없어요. 팔꿉 굽힘은 **C5**부터예요.", "C4 완전 손상 환자는 팔꿉 굽힘이 **불가능**하다(C5부터).", "C4 어깨 으쓱, C5 팔꿉 굽힘", 4),
"c392:xt51_1_80": ("어깨올림·**부분 호흡**", "어깨올림과 부분 호흡만 가능하고 팔다리 감각이 없는 완전 손상 수준은 **C4**예요.", "'C5'로 바꾸면 틀려요.", "C3·4·5가 가로막을 살린다", 4),
"c393:xo53_1_82": ("**30점 만점** 선별 검사", "30점 만점 인지 선별 검사는 **MMSE**예요. 임상치매평가척도(CDR)는 치매 중증도를 단계로 매겨요.", "30점 만점 선별 검사는 **MMSE**다.", "MMSE 30점, CDR 단계", 4),
"c393:xt53_1_82": ("30점 만점 **치매 선별**", "30점 만점 치매 선별 도구는 **간이정신상태검사(MMSE)** 예요.", "'임상치매평가척도'로 바꾸면 틀려요.", "MMSE = 30점", 4),
"c394:xo52_1_88": ("**편측무시** 평가", "딕스-홀파이크는 **양성 돌발 체위현훈(BPPV)** 검사예요. 편측무시는 선 나누기·지우기 검사 등으로 봐요.", "딕스-홀파이크 검사는 **어지럼(BPPV)** 검사다.", "딕스-홀파이크 = 이석", 3),
"c394:xo52_2_30": ("**관념운동** 행위상실증", "관념운동 행위상실증은 개념은 있으나 **지시하면 못하는** 상태예요. 도구 사용 개념 자체를 잃는 것은 관념 행위상실증이에요.", "도구 사용 개념 자체를 잃는 것은 **관념** 행위상실증이다.", "관념 = 개념 상실, 관념운동 = 지시 수행 불가", 4),
"c394:xo51_1_87": ("**관념** 행위상실증", "습관적 동작은 되지만 지시하면 못하는 것은 **관념운동** 행위상실증이에요. 관념 행위상실증은 순서·개념 자체를 잃어요.", "습관적 동작은 하나 지시하면 못하는 것은 **관념운동** 행위상실증이다.", "지시에 못하면 관념운동", 4),
"c394:xo50_2_31": ("**실어증**과 **행위상실증**", "배운 동작을 못하는 것은 **행위상실증**이고, 실어증은 **말(언어)** 의 장애예요.", "배운 동작을 수행하지 못하는 상태는 **행위상실증**이다.", "동작 = 행위상실, 말 = 실어", 3),
"c395:xo53_1_84": ("**급성기 의식** 평가", "급성기 의식 수준은 **글래스고 혼수척도(GCS)** 로 평가해요. 글래스고 결과척도는 회복 결과를 봐요.", "급성기 의식 수준은 **글래스고 혼수척도**로 평가한다.", "혼수척도 = 의식, 결과척도 = 예후", 4),
"c395:xo52_1_83": ("**란초 2단계**", "란초 2단계는 **전반적 반응** 단계예요. 흥분·공격적 상태는 **4단계(혼란-흥분)** 예요.", "란초 2단계는 **전반적 반응** 단계다(흥분은 4단계).", "1 무반응, 2 전반적, 3 국소적, 4 흥분", 4),
"c395:xo51_1_83": ("글래스고 결과척도 **5등급**", "글래스고 결과척도는 1등급이 사망, **5등급이 양호한 회복**이에요.", "글래스고 결과척도 5등급은 **양호한 회복**이다.", "1 사망, 5 회복", 3),
"c395:xo50_1_81": ("GCS **13점 이상**", "GCS 13~15점은 **경도**, 9~12점은 중등도, 8점 이하는 중증이에요.", "GCS 13점 이상은 **경도** 손상이다.", "8 이하 중증, 9~12 중등, 13~15 경도", 5),
"c396:xo53_1_86": ("감각·ROM까지 **평가**", "운동 회복에 감각·균형·관절운동범위까지 보는 것은 **퓨글-마이어**예요. 울프는 팔·손 과제 수행 시간과 기능 점수를 봐요.", "감각·관절운동범위까지 평가하는 것은 **퓨글-마이어**다.", "퓨글-마이어 = 종합, 울프 = 팔 과제 시간", 4),
"c396:xo52_1_69": ("**헌팅턴병 평가척도**", "통합된 헌팅턴병 평가척도는 **헌팅턴병(무도증)** 평가 도구예요. 파킨슨병은 UPDRS·Hoehn & Yahr 등을 써요.", "통합된 헌팅턴병 평가척도는 **헌팅턴병** 평가에 쓴다.", "이름에 병이 들어 있다", 3),
"c396:xo52_1_84": ("**17개 과제** 수행 시간", "팔·손 과제 17개의 수행 시간과 기능 점수를 재는 것은 **울프 운동기능검사**예요.", "17개 항목 수행 시간을 재는 것은 **울프 운동기능검사**다.", "울프 17과제 시간", 4),
"c396:xo51_1_84": ("**퓨글-마이어** 평가 내용", "퓨글-마이어는 **운동 회복**·감각·균형·관절운동범위를 봐요. 편측무시는 평가하지 않아요.", "퓨글-마이어 평가는 **운동 회복**을 평가한다.", "퓨글-마이어 = 뇌졸중 운동 회복", 4),
"c396:xo51_1_85": ("**울프 운동기능검사**", "울프 검사는 **팔 운동기능** 평가 도구예요. 실조는 ICARS 등으로 평가해요.", "울프 운동기능검사는 **팔 운동기능** 평가 도구다.", "울프 = 팔", 3),
"c396:xo50_1_84": ("**Hoehn & Yahr** 척도", "Hoehn & Yahr 척도는 **파킨슨병** 진행 단계를 나눠요.", "Hoehn & Yahr 척도는 **파킨슨병** 단계를 평가한다.", "Hoehn & Yahr = 파킨슨", 4),
"c397:xo53_1_87": ("감각 정상 + **세동전위** + 반사 소실", "감각 정상 + 세동전위 + 반사 소실은 **앞뿔세포(아래운동신경세포)** 병변 양상이에요. 길랭-바레증후군은 감각 이상이 함께 올 수 있어요.", "감각 정상 + 세동전위 + 반사 소실은 **앞뿔세포** 병변 양상이다.", "감각 멀쩡 + 운동만 = 앞뿔세포", 3),
"c397:xt53_1_87": ("감각 정상 + **세동전위** + 반사 소실", "감각은 정상이고 운동만 손상된 아래운동신경세포 양상이에요. 이 문항의 정답은 **진행성 근위축증**이에요.", "'길랭-바레증후군'으로 바꾸면 틀려요.", "감각 멀쩡 + 운동만 = 앞뿔세포", 3),
"c397:xo50_2_48": ("**BPPV** 치료", "딕스-홀파이크 양성인 BPPV는 이석이 반고리관에 들어간 것이라 **에플레이 처치**로 이석을 옮겨요. 발살바 조작은 치료법이 아니에요.", "양성 돌발 체위현훈에는 **에플레이 처치**를 한다.", "이석은 에플레이로 굴려 넣는다", 4),
"c397:xt50_2_48": ("딕스-홀파이크 양성 **치료**", "자세를 바꿀 때 어지럽고 딕스-홀파이크 양성이면 BPPV이고, 치료는 **에플레이(이석 정복) 처치**예요.", "'발살바 조작'으로 바꾸면 틀려요.", "BPPV = 에플레이", 4),
"c398:xo50_1_86": ("**큰볼기근** 신경", "큰볼기근은 **아래볼기신경**이 지배해요. 위볼기신경은 중간볼기근(트렌델렌부르크 보행)이에요.", "큰볼기근 보행은 **아래볼기신경** 손상에서 나타난다.", "큰 = 아래, 중간 = 위", 5),
"c398:xt50_1_86": ("큰볼기근 약화 **신경**", "디딤기에 몸을 뒤로 젖히는 큰볼기근 보행은 **아래볼기신경** 손상이에요.", "'위볼기신경'으로 바꾸면 틀려요.", "큰 = 아래볼기", 5),
"c398:xo50_1_104": ("**넙다리네갈래근** 약화 보행", "넙다리네갈래근이 약하면 무릎이 꺾이지 않게 몸을 앞으로 숙여 **무릎을 편 채** 버텨요.", "넙다리네갈래근이 약하면 **무릎을 편 채** 체중을 싣는다.", "무릎 꺾일까 봐 펴서 잠근다", 4),
"c398:xt50_1_104": ("발꿈치닿기 후 **몸통 앞으로**", "넙다리신경 병증으로 넙다리네갈래근이 약하면 몸통을 앞으로 기울여 무릎을 펴는 **넙다리네갈래근 회피 보행**이 나타나요.", "'큰볼기근 보행'으로 바꾸면 틀려요.", "앞으로 숙이기 = 넙다리네갈래근", 4),
}
